#!/usr/bin/env node

const fs = require('node:fs');

const args = process.argv.slice(2);
const lineMode = args[0] === '--lines';
const fileArgs = lineMode ? args.slice(1) : args;
if (fileArgs.length !== 1 || fileArgs[0].startsWith('-')) {
  process.stderr.write('Usage: node bin/tally.js [--lines] <file-path>\n');
  process.exitCode = 1;
} else {
  try {
    const contents = fs.readFileSync(fileArgs[0], 'utf8');
    let count;
    if (lineMode) {
      const breaks = contents.match(/\r\n|\r|\n/g) || [];
      count = contents.length === 0 ? 0 : breaks.length + (/[\r\n]$/.test(contents) ? 0 : 1);
    } else {
      count = contents.split(/[ \r\n]+/).filter(Boolean).length;
    }
    process.stdout.write(`${count}\n`);
  } catch (error) {
    process.stderr.write(`Cannot read file: ${error.message}\n`);
    process.exitCode = 1;
  }
}
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { test } = require('node:test');

const command = path.join(__dirname, '..', 'bin', 'tally.js');

function runWithContents(contents, flags = []) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'tally-'));
  const file = path.join(directory, 'sample.txt');
  try {
    fs.writeFileSync(file, contents);
    return spawnSync(process.execPath, [command, ...flags, file], { encoding: 'utf8' });
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
}

test('counts words separated by spaces and line breaks', () => {
  const result = runWithContents('one two\nthree');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '3\n');
  assert.equal(result.stderr, '');
});

test('ignores repeated separators and returns zero for an empty file', () => {
  assert.equal(runWithContents(' one  \n\n two ').stdout, '2\n');
  assert.equal(runWithContents('').stdout, '0\n');
});

test('tabs are not word separators', () => {
  assert.equal(runWithContents('one\ttwo three').stdout, '2\n');
});

test('rejects missing, extra, and flag arguments', () => {
  for (const args of [[], ['a', 'b'], ['--lines'], ['--unknown']]) {
    const result = spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
    assert.notEqual(result.status, 0);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /Usage:/);
  }
});

test('reports a missing file on standard error', () => {
  const result = spawnSync(process.execPath, [command, path.join(os.tmpdir(), 'tally-file-does-not-exist')], { encoding: 'utf8' });
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /Cannot read file:/);
});

test('counts LF lines, including blank lines and a final line without a break', () => {
  assert.equal(runWithContents('one two\nthree', ['--lines']).stdout, '2\n');
  assert.equal(runWithContents('one\n\n', ['--lines']).stdout, '2\n');
});

test('counts CR and CRLF as one break each', () => {
  assert.equal(runWithContents('one\r\ntwo\r\n', ['--lines']).stdout, '2\n');
  assert.equal(runWithContents('one\rtwo', ['--lines']).stdout, '2\n');
});

test('returns zero lines for an empty file', () => {
  const result = runWithContents('', ['--lines']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '0\n');
  assert.equal(result.stderr, '');
});

test('rejects repeated, unknown, and misplaced flags', () => {
  for (const args of [['--lines', '--lines', 'file'], ['--wrong', 'file'], ['file', '--lines']]) {
    const result = spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
    assert.notEqual(result.status, 0);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /Usage:/);
  }
});
